const clock=new THREE.Clock();
function log(text){const feed=$('#feed'),row=document.createElement('div');row.innerHTML='<span>✦</span>'+text;feed.prepend(row);while(feed.children.length>3)feed.lastChild.remove()}
let toastTimer;function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateBars(){$('#health-fill').style.width=Math.max(0,health)+'%';$('#stamina-fill').style.width=Math.max(0,stamina)+'%';$('#health-text').textContent=Math.ceil(health)+' / 100';$('#stamina-text').textContent=Math.ceil(stamina)+' / 100';$('#shard-count').textContent=shards;$('#ore-count').textContent=ore}
function updateMission(){const isGod=cleared>=5;$('#progress-title').innerHTML=isGod?'REGIONAL GOD &nbsp;·&nbsp; FINAL HUNT':`Warden Hunt &nbsp; ${Math.min(cleared,5)} / 5`;$('#task-dots').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i<cleared?'done':''}"></i>`).join('');if(isGod){$('#contract-name').textContent='Defeat the Hollow God';$('#contract-copy').textContent='Five wardens have fallen. The god has taken form at the rift — end the convergence.';return}$('#contract-name').textContent='Find the '+wardenNames[cleared];$('#contract-copy').textContent=wardenDescriptions[cleared]}
function updateGame(dt){if(!gameStarted)return;attackCooldown=Math.max(0,attackCooldown-dt);enemyCooldown=Math.max(0,enemyCooldown-dt);let dx=0,dz=0;if(keys.KeyW||keys.ArrowUp)dz-=1;if(keys.KeyS||keys.ArrowDown)dz+=1;if(keys.KeyA||keys.ArrowLeft)dx-=1;if(keys.KeyD||keys.ArrowRight)dx+=1;dx+=touchX;dz+=touchY;const len=Math.hypot(dx,dz);if(len>.08&&!resting){const speed=mounted?5.4:3.65;player.position.x+=dx/Math.max(1,len)*speed*dt;player.position.z+=dz/Math.max(1,len)*speed*dt;player.position.x=THREE.MathUtils.clamp(player.position.x,-21,21);player.position.z=THREE.MathUtils.clamp(player.position.z,-22,22);player.userData.face=Math.atan2(dx,dz);if(stamina>0)stamina=Math.max(0,stamina-dt*1.35);if(companion){if(mounted){companion.position.copy(player.position);companion.position.y=.12;companion.rotation.y=player.userData.face}else{const follow=new THREE.Vector3(player.position.x-1.15,0,player.position.z+1.25);companion.position.lerp(follow,.07)}}}else if(!resting&&stamina<100)stamina=Math.min(100,stamina+dt*.65);
 const distance=player.position.distanceTo(enemy.position);if(distance<2.2&&enemyCooldown<=0){enemyCooldown=1.45;health-=cleared===5?18:13;if(health<=0){health=0;dead=true;$('#defeat').classList.add('show');log('Your companion carries you to safety.')}else toast('A warden strikes! Keep moving.');updateBars()}
 if(resting){if((performance.now()-restStart)>=10000){resting=false;stamina=100;$('#rest-btn').classList.remove('active');toast('Fully rested. Stamina restored.');log('You take a ten-second rest. Stamina restored.')}else stamina=Math.min(100,(performance.now()-restStart)/10000*100)}updateBars();if(companion&&!mounted){companion.rotation.y=Math.sin(worldTime*2)*.08}}
let touchX=0,touchY=0;const stick=$('#touch-stick'),knob=$('#stick-knob');let stickPointer=null;stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let x=e.clientX-cx,y=e.clientY-cy,l=Math.hypot(x,y),max=39;if(l>max){x=x/l*max;y=y/l*max}knob.style.transform=`translate(${x}px,${y}px)`;touchX=x/max;touchY=y/max}function resetStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;touchX=touchY=0;knob.style.transform=''}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
function startGame(){if(gameStarted)return;gameStarted=true;$('#menu').style.opacity=0;$('#menu').style.transform='translateY(-42%)';setTimeout(()=>$('#menu').style.display='none',300);$('#game-ui').style.display='block';document.querySelector('.bottomline').style.display='none';updateMission();log('The wilds are alive. Find the first warden.');toast('Your expedition begins.');}
function doAttack(ranged=false){if(!gameStarted||dead||attackCooldown>0)return;if(stamina<8){toast('Too tired to strike. Rest for a moment.');return}stamina=Math.max(0,stamina-8);attackCooldown=ranged?.75:.62;const range=ranged?11:2.9,dist=player.position.distanceTo(enemy.position);if(ranged&&!hasBow){toast('Forge the Starfall bow first.');return}if(dist<=range){const damage=ranged?24:weaponDamage;enemyHp-=damage;enemy.userData.core.material.emissiveIntensity=1.25;setTimeout(()=>{if(enemy?.userData?.core)enemy.userData.core.material.emissiveIntensity=.16},120);enemy.position.x+=(enemy.position.x-player.position.x)*.04;toast(`${ranged?'Starfall arrow':'Strike'} — ${damage} damage`);if(enemyHp<=0)defeatEnemy()}else toast(ranged?'Arrow loosed — no target in range.':'Move closer to the warden.');updateBars()}
function defeatEnemy(){if(cleared<5){shards+=2+Math.floor(Math.random()*3);ore+=1+Math.floor(Math.random()*2);cleared++;log(`${wardenNames[cleared-1]} defeated · precious shards recovered.`);toast('Warden defeated! +shards +ore');updateMission();spawnEnemy()}else{toast('The Hollow God falls. The region is free!');log('REGIONAL GOD DEFEATED · NEXT FRONTIER UNLOCKED');cleared=0;shards+=12;ore+=8;health=100;stamina=100;spawnEnemy();$('#mission .mission small');$('#progress-title').innerHTML='FRONTIER 02 &nbsp;·&nbsp; DAY 02';$('#contract-name').textContent='New frontier unlocked';$('#contract-copy').textContent='A fresh region opens beyond the rift. Five new wardens are already waiting.';$('#task-dots').innerHTML=Array(5).fill('<i></i>').join('');}updateBars()}
function openModal(title,eyebrow,body){$('#modal').innerHTML=`<div class="modal-head"><div><small>${eyebrow}</small><h2>${title}</h2></div><button class="close" aria-label="Close">×</button></div>${body}`;$('#modal-backdrop').classList.add('open');$('#modal .close').onclick=()=>$('#modal-backdrop').classList.remove('open');$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')e.currentTarget.classList.remove('open')}}
function showMount(){if(chosenMount){toast(`Bonded companion: ${chosenMount}. A bond is for life.`);return}openModal('Choose one companion','A bond is for the whole expedition',`<p class="modal-copy">Every wayfarer may bond with exactly one creature. It will carry you and help in battle. This choice cannot be changed.</p><div class="card-list">${animals.map((a,i)=>`<button class="choice-card" data-mount="${i}"><span class="card-left"><span class="choice-icon">${a.icon}</span><span><b>${a.name} · ${a.kind}</b><small>${a.desc}</small></span></span><span class="card-status">BOND ↗</span></button>`).join('')}</div>`);document.querySelectorAll('[data-mount]').forEach(btn=>btn.onclick=()=>{const a=animals[+btn.dataset.mount];chosenMount=a.name;scene.remove(companion);companion=makeAnimalMesh(a.color);scene.add(companion);companion.position.copy(player.position).add(new THREE.Vector3(-1,0,1.3));$('#mount-btn').textContent=`◈ ${a.name}`;$('#modal-backdrop').classList.remove('open');log(`${a.name} bonds with you. Your one companion, for life.`);toast(`${a.name} joined your expedition.`)})}
const recipes=[{name:'Pulse blade',icon:'⚔',cost:'2 shards · 1 ore',s:2,o:1,desc:'A bright close-range weapon. Current damage 35 → 48.',make:()=>{weapon='Pulse blade';weaponDamage=48}},{name:'Starfall bow',icon:'➶',cost:'3 shards · 2 ore',s:3,o:2,desc:'A futuristic bow that strikes from long range.',make:()=>{hasBow=true;weapon='Starfall bow'}},{name:'Aegis armor',icon:'⬡',cost:'2 shards · 3 ore',s:2,o:3,desc:'Reinforced armor. Increases maximum health by 30.',make:()=>{health=Math.min(100,health+30)}}];
function showForge(){openModal('Field forge','Build your kit from warden drops',`<p class="modal-copy">Shards: <b style="color:var(--gold)">${shards}</b> &nbsp;·&nbsp; Ore: <b style="color:var(--gold)">${ore}</b><br>Every warden leaves rare elements behind. Plan your build before the next fight.</p><div class="craft-grid">${recipes.map((r,i)=>`<div class="craft-item"><b>${r.icon} &nbsp;${r.name}</b><p>${r.desc}<br><span style="color:#dfca92">${r.cost}</span></p><button data-craft="${i}" ${shards<r.s||ore<r.o?'disabled':''}>FORGE</button></div>`).join('')}</div>`);document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const r=recipes[+b.dataset.craft];if(shards<r.s||ore<r.o)return;shards-=r.s;ore-=r.o;r.make();updateBars();$('#modal-backdrop').classList.remove('open');log(`${r.name} forged from the elements.`);toast(`${r.name} ready.`);if(r.name==='Starfall bow')$('#bow-btn').classList.add('active')})}
function forage(){if(!gameStarted||dead)return;const fruit=Math.random();if(fruit<.18){health=Math.max(1,health-17);toast('Poison fruit! Health −17.');log('A beautiful fruit was poisonous.')}else{const heal=fruit<.47?12:25;health=Math.min(100,health+heal);toast(`Wild fruit restores ${heal} health.`);log(`Foraged a ripe fruit. +${heal} health.`)}updateBars()}
function beginRest(){if(!gameStarted||dead||resting)return;resting=true;restStart=performance.now();$('#rest-btn').classList.add('active');toast('Resting — 10 seconds for full stamina.');log('You settle in for a ten-second rest.')}
function showParty(){openModal('Expedition party','Travel is better together',`<p class="modal-copy">Invite up to two friends to your expedition. A party code lets friends join the same local session.</p><div class="party-code" id="invite-code">WILD-${Math.random().toString(36).slice(2,6).toUpperCase()}</div><button class="primary" id="copy-code" style="width:100%">COPY INVITE CODE</button><p class="notice" style="margin-top:12px">This preview runs as a solo expedition. Online multiplayer needs a game server; party slots are shown for the co-op design.</p>`);$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText($('#invite-code').textContent);toast('Invite code copied.')}catch{toast('Invite code: '+$('#invite-code').textContent)}}}
$('#start-btn').onclick=startGame;$('#party-btn').onclick=showParty;$('#party-ingame').onclick=showParty;$('#mount-btn').onclick=showMount;$('#craft-btn').onclick=showForge;$('#eat-btn').onclick=forage;$('#attack-btn').onclick=()=>doAttack(false);$('#bow-btn').onclick=()=>doAttack(true);$('#rest-btn').onclick=beginRest;$('#revive-btn').onclick=()=>{dead=false;health=65;stamina=100;player.position.set(0,0,7);$('#defeat').classList.remove('show');updateBars();log('Your companion gets you back on your feet.')};
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space')doAttack(false);if(e.code==='KeyE')forage();if(e.code==='KeyR')beginRest();if(e.code==='KeyB')doAttack(true);if(e.code==='Escape')$('#modal-backdrop').classList.remove('open')},{passive:false});window.addEventListener('keyup',e=>keys[e.code]=false);$('#task-dots').innerHTML=Array(5).fill('<i></i>').join('');init3d();updateBars();
</script></body></html>

